#!/usr/bin/env python3
"""Regenerates Sources/AIUsage/ProviderIcons.swift from Assets/ProviderMarks/*.png.

The PNGs are embedded as base64 so the app needs no SwiftPM resource bundle."""
import base64, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
marks = sorted((root / "Assets/ProviderMarks").glob("provider-*.png"))
lines = [
    "// Generated by Scripts/embed_marks.py from Assets/ProviderMarks (see NOTICE.md there). Do not edit.",
    "import Foundation",
    "",
    "enum ProviderIconData {",
    "    static let png: [String: String] = [",
]
for p in marks:
    name = p.stem.removeprefix("provider-")
    lines.append(f'        "{name}": "{base64.b64encode(p.read_bytes()).decode()}",')
lines += ["    ]", "}", ""]
(root / "Sources/AIUsage/ProviderIcons.swift").write_text("\n".join(lines))
print(f"embedded {len(marks)} marks")
